here<-dirname(normalizePath(sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)),winslash='/'));source(file.path(here,'common.R'))
a<-args_named();out<-normal(need(a,'out'),FALSE);stopifnot(!dir.exists(out));dir.create(out,recursive=TRUE)
required<-c('jsonlite','DBI','RSQLite','digest','raster','sp')
available<-vapply(required,requireNamespace,logical(1),quietly=TRUE)
versions<-vapply(required,function(p)if(available[[p]])as.character(packageVersion(p))else NA_character_,character(1))
files<-list.files(dirname(here),pattern='[.]R$',recursive=TRUE,full.names=TRUE)
parsed<-vapply(files,function(f){parse(f);TRUE},logical(1))
writej(list(status=if(all(available)&&all(parsed))'PASS'else'MISSING_DEPENDENCIES',R=R.version.string,packages=as.list(versions),parsed_R_scripts=length(files),scope='Current execution, extraction, packaging and paired-summary modules; later plotting dependencies will be added when integrated.'),file.path(out,'environment.json'))
capture.output(sessionInfo(),file=file.path(out,'sessionInfo.txt'))
stopifnot(all(available),all(parsed));cat('Environment and R syntax checks PASS\n')
